from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        if kind == 'put':
            value = op[3]
            # check existing entry
            if key in cache:
                _, write_time = cache[key]
                if t >= write_time + ttl:
                    # expired, treat as absent
                    del cache[key]

            if key in cache:
                # still present (not expired) -> update
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                # absent -> need to possibly evict
                if len(cache) >= capacity:
                    # evict LRU
                    cache.popitem(last=False)
                cache[key] = (value, t)
                cache.move_to_end(key)

        elif kind == 'get':
            if key in cache:
                val, write_time = cache[key]
                if t >= write_time + ttl:
                    # expired
                    del cache[key]
                    results.append(-1)
                else:
                    results.append(val)
                    cache.move_to_end(key)
            else:
                results.append(-1)

    return results

